package ControlStatements;

public class Switch {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		String day = "sun";
		
		switch(day) {
		
		case "sun" : System.out.println("Sun");
		break ;
		

		case "mon" : System.out.println("mon");
		break ;
		

		case "tus" : System.out.println("Tus");
		break ;
		

		case "wend" : System.out.println("wend");
		break ;
		

		case "Thu" : System.out.println("Thu");
		break ;
		

		case "fri" : System.out.println("fri");
		break ;
		

		case "sat" : System.out.println("sat");
		break ;
		
		default : System.out.println("invalid ");
		
		
		
		
		
		
		
		}

	}

}
